Definition mk_1RB____0LC1RD_1LB1RC_1LC0RD (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_1RB____0LC1RD_1LB1RC_1LC0RD.

(** 1RB---_0LC1RD_1LB1RC_1LC0RD *)
(** 1RB---_0LC1RD_1LB1RC_1LC0RD -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB____0LC1RD_1LB1RC_1LC0RD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => None
  | StB, S0 => mk S0 DL StC | StB, S1 => mk S1 DR StD
  | StC, S0 => mk S1 DL StB | StC, S1 => mk S1 DR StC
  | StD, S0 => mk S1 DL StC | StD, S1 => mk S0 DR StD end.

(** Its mirror 1LB---_0RC1LD_1RB1LC_1RC0LD: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB____0LC1RD_1LB1RC_1LC0RD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => None
  | StB, S0 => mk S0 DR StC | StB, S1 => mk S1 DL StD
  | StC, S0 => mk S1 DR StB | StC, S1 => mk S1 DL StC
  | StD, S0 => mk S1 DR StC | StD, S1 => mk S0 DL StD end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB____0LC1RD_1LB1RC_1LC0RD : list Instr := [(StA, S1); (StA, S0)].
Definition tmw_1RB____0LC1RD_1LB1RC_1LC0RD : TM := tm_wrap_trs tmm_1RB____0LC1RD_1LB1RC_1LC0RD pins_1RB____0LC1RD_1LB1RC_1LC0RD.
Local Notation tm := tmw_1RB____0LC1RD_1LB1RC_1LC0RD.

Lemma mirror_ok_1RB____0LC1RD_1LB1RC_1LC0RD : mirror_tm tm_1RB____0LC1RD_1LB1RC_1LC0RD = tmm_1RB____0LC1RD_1LB1RC_1LC0RD.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

