Lemma gen_1RB____0LC1RD_1LB1RC_1LC0RD : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ip q0 ++ [S1]) [] i AI1_1RB____0LC1RD_1LB1RC_1LC0RD) = lift (Cin (Pos.succ v)).
