(** The chain into this family lands on its anchor up to 0/0
    trailing blanks. *)
Lemma gbo_1RB____0LC1RD_1LB1RC_1LC0RD : forall j, lift (cden [] [] j BB1_1RB____0LC1RD_1LB1RC_1LC0RD) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB____0LC1RD_1LB1RC_1LC0RD = (StB, (rep [S1;S0] j ++ [S1;S1], S0, [S0;S1]))).
  { unfold cden, BB1_1RB____0LC1RD_1LB1RC_1LC0RD, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
