  assert (HC : Cin (pow2 j) = (StB, (rep [S1;S0] j ++ [S1;S1], S0, [S0;S1]))).
  { unfold Cin_1RB____0LC1RD_1LB1RC_1LC0RD. rewrite epow2_1RB____0LC1RD_1LB1RC_1LC0RD.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
