(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB____0LC1RD_1LB1RC_1LC0RD : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB____0LC1RD_1LB1RC_1LC0RD p (pow2 j)).
  - exists (4 * j + 9), (cden [] [] j BB1_1RB____0LC1RD_1LB1RC_1LC0RD).
    split; [lia|]. split; [| exact (gbo_1RB____0LC1RD_1LB1RC_1LC0RD j)].
    rewrite (gso_1RB____0LC1RD_1LB1RC_1LC0RD p j E).
    exact (srun_sound tm true true chb_1RB____0LC1RD_1LB1RC_1LC0RD B0_1RB____0LC1RD_1LB1RC_1LC0RD BB1_1RB____0LC1RD_1LB1RC_1LC0RD 4 9
             run_boot_1RB____0LC1RD_1LB1RC_1LC0RD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 15), (cden [] [] j B1_1RB____0LC1RD_1LB1RC_1LC0RD).
    split; [| exact (geo_1RB____0LC1RD_1LB1RC_1LC0RD p j E)].
    rewrite (gxi_1RB____0LC1RD_1LB1RC_1LC0RD j).
    exact (srun_sound tm true true che_1RB____0LC1RD_1LB1RC_1LC0RD BE0_1RB____0LC1RD_1LB1RC_1LC0RD B1_1RB____0LC1RD_1LB1RC_1LC0RD 4 15
             run_exit_1RB____0LC1RD_1LB1RC_1LC0RD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB____0LC1RD_1LB1RC_1LC0RD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB____0LC1RD_1LB1RC_1LC0RD p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB____0LC1RD_1LB1RC_1LC0RD p j' E).
Qed.

(** ** Bootstrap *)

Lemma bootq_1RB____0LC1RD_1LB1RC_1LC0RD : stepn tmm_1RB____0LC1RD_1LB1RC_1LC0RD 13 InitES = Some (lift (Cc 1)).
Proof.
  assert (H : match csteps tmm_1RB____0LC1RD_1LB1RC_1LC0RD 13 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
