(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB____0LC1RD_1LB1RC_1LC0RD : existsb (fun tg => cfires tmm_1RB____0LC1RD_1LB1RC_1LC0RD c0 13 tg) pins_1RB____0LC1RD_1LB1RC_1LC0RD = true.
