  unfold Cin_1RB____1LB1RC_0RD0LB_0RB0RC, cden, AI1_1RB____1LB1RC_0RD0LB_0RB0RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
