(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB____1LB1RC_0RD0LB_0RB0RC : existsb (fun tg => cfires tmm_1RB____1LB1RC_0RD0LB_0RB0RC c0 9 tg) pins_1RB____1LB1RC_0RD0LB_0RB0RC = true.
