(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB____1LB1RC_0RD0LB_0RB0RC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB____1LB1RC_0RD0LB_0RB0RC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB____1LB1RC_0RD0LB_0RB0RC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB____1LB1RC_0RD0LB_0RB0RC p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_1RB____1LB1RC_0RD0LB_0RB0RC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB____1LB1RC_0RD0LB_0RB0RC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_1RB____1LB1RC_0RD0LB_0RB0RC t p (pow2 j)).
  - exists (4 * j + 8), (cden [] [] j BB1_1RB____1LB1RC_0RD0LB_0RB0RC). split;
      [| exact (gbo_1RB____1LB1RC_0RD0LB_0RB0RC j)].
    rewrite (gso_1RB____1LB1RC_0RD0LB_0RB0RC p j E).
    exact (srun_sound tm true true chb_1RB____1LB1RC_0RD0LB_0RB0RC B0_1RB____1LB1RC_0RD0LB_0RB0RC BB1_1RB____1LB1RC_0RD0LB_0RB0RC 4 8
             run_boot_1RB____1LB1RC_0RD0LB_0RB0RC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
