Lemma fireo_1RB____1LB1RC_1LB0RD_0RC0LB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB____1LB1RC_1LB0RD_0RC0LB = Some t ->
  forall p j, cview p = (S j, None) ->
